class SyncJob
{
    void Run(BlogContext context)
    {
        // Breaking change #4: EF 9 uses ReadItem for single-partition queries by default,
        // which requires sync over async. Use ToListAsync or keep ToList — no issue here.
        var blogs = context.Blogs.ToList();
        foreach (var b in blogs) { b.Name = b.Name.Trim(); }

        // Breaking change #5: EF 9 uses patch-based (partial) updates instead of full
        // document replace. This is usually fine, but know that SaveChanges now sends
        // only changed properties, not the full document.
        context.SaveChanges();
    }

    // Breaking change #6: Raw SQL queries referencing "Discriminator" must be updated
    // if you did NOT configure HasDiscriminator("Discriminator") in OnModelCreating.
    // Since we preserved the old name above, existing queries like:
    //   SELECT * FROM c WHERE c.Discriminator = 'Blog'
    // continue to work. Without that fix, you'd need:
    //   SELECT * FROM c WHERE c["$type"] = 'Blog'
}

