{
    public DbSet<Blog> Blogs => Set<Blog>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Blog>(entity =>
        {
            // Breaking change #1: EF 9 renamed "Discriminator" to "$type".
            // Existing documents use "Discriminator", so we must preserve it.
            entity.HasDiscriminator<string>("Discriminator");

            // Breaking change #2: EF 9 changed the shadow "__id" format from
            // "EntityType|Key" to just "Key". Existing documents use "Blog|<key>",
            // so we restore the old format with a custom value generator.
            entity.Property<string>("__id")
                  .HasValueGenerator<BlogCosmosIdGenerator>();

            // Breaking change #3: EF 9 no longer supports HasIndex() for Cosmos DB
            // entities — Cosmos manages its own indexing policy. Removed HasIndex().
        });
    }
}

